# Generated by splitting app.py lines 6193-7407. Keep execution order in wangcai_app/startup/loader.py.
COMPLETED_IDLE_PROMPT_MARKER = "【已完结】"
UNNAMED_IDLE_ARTIFACT_TITLE = "未命名成果"
MALFORMED_IDLE_ARTIFACT_SUMMARY = "idle agent returned malformed JSON; saved raw content"
IDLE_SERIES_TITLE_MAX_CHARS = 80


def effective_idle_agent_custom_prompt(prompt: str) -> str:
    prompt = str(prompt or "").strip()
    if COMPLETED_IDLE_PROMPT_MARKER in prompt:
        return ""
    return prompt


def completed_idle_agent_custom_prompt(prompt: str) -> str:
    prompt = str(prompt or "").strip()
    if not prompt:
        return ""
    if COMPLETED_IDLE_PROMPT_MARKER in prompt:
        return prompt
    return f"{prompt}\n{COMPLETED_IDLE_PROMPT_MARKER}"


def parse_idle_count_text(value: object) -> Optional[int]:
    text = normalize_idle_artifact_terms(str(value or "")).strip()
    if not text:
        return None
    digits = text.translate(str.maketrans("０１２３４５６７８９", "0123456789"))
    match = re.search(r"\d+", digits)
    if match:
        number = int(match.group(0))
        return number if number > 0 else None
    chinese_digits = {
        "零": 0,
        "一": 1,
        "二": 2,
        "两": 2,
        "三": 3,
        "四": 4,
        "五": 5,
        "六": 6,
        "七": 7,
        "八": 8,
        "九": 9,
    }
    if text == "十":
        return 10
    match = re.search(r"([一二两三四五六七八九])?十([一二三四五六七八九])?", text)
    if match:
        tens = chinese_digits.get(match.group(1) or "一", 1)
        ones = chinese_digits.get(match.group(2) or "零", 0)
        return tens * 10 + ones
    if len(text) == 1 and text in chinese_digits:
        return chinese_digits[text]
    return None


def canonical_idle_series_title(value: object) -> str:
    title = normalize_idle_artifact_terms(str(value or "")).strip()
    title = re.sub(r"^[《「『【\[\(（\s]+", "", title)
    title = re.sub(r"[》」』】\]\)）\s]+$", "", title)
    title = re.sub(r"\s+", " ", title).strip(" ：:，,。；;、")
    return title[:IDLE_SERIES_TITLE_MAX_CHARS]


def idle_series_title_key(value: object) -> str:
    return re.sub(r"\s+", "", canonical_idle_series_title(value)).lower()


def idle_series_title_variants(series_title: str) -> List[str]:
    canonical = canonical_idle_series_title(series_title)
    if not canonical:
        return []
    variants = [canonical, f"《{canonical}》"]
    seen: List[str] = []
    for item in variants:
        if item and item not in seen:
            seen.append(item)
    return seen


def idle_series_directive_from_prompt(prompt: str) -> Dict[str, object]:
    text = normalize_idle_artifact_terms(str(prompt or "")).replace(COMPLETED_IDLE_PROMPT_MARKER, "").strip()
    if not text:
        return {"series_title": "", "target_count": None, "explicit_series": False}
    count_match = re.search(
        r"(?:连载|續寫|续写|连续|系列|写成|生成|创作)?\s*([0-9０-９一二两三四五六七八九十]{1,8})\s*(?:篇|集|章|回)",
        text,
    )
    target_count = parse_idle_count_text(count_match.group(1)) if count_match else None
    quoted = [canonical_idle_series_title(item) for item in re.findall(r"《([^》]{1,120})》", text)]
    series_title = next((item for item in quoted if item), "")
    if not series_title and count_match:
        prefix = text[: count_match.start()]
        prefix = re.split(r"[\n。；;]", prefix)[-1]
        prefix = re.sub(r"(?:请|帮我|给我|来|搞|写|生成|创作|继续|续写|连载|系列|故事|作品|一组|一些)+", "", prefix)
        series_title = canonical_idle_series_title(prefix)
    if not series_title and count_match:
        leading_clause = re.split(r"[\n。；;，,]", text, maxsplit=1)[0]
        leading_clause = re.sub(r"(?:请|帮我|给我|来|搞|写|生成|创作|继续|续写|连载|系列|故事|作品|一组|一些)+", "", leading_clause)
        series_title = canonical_idle_series_title(leading_clause)
    explicit_series = bool(series_title and (target_count or "连载" in text or "续写" in text or "系列" in text))
    return {
        "series_title": series_title,
        "target_count": target_count,
        "explicit_series": explicit_series,
    }


def idle_series_status(series_title: str) -> Dict[str, object]:
    canonical = canonical_idle_series_title(series_title)
    if not canonical:
        return {"series_title": "", "total_count": 0, "max_episode": 0, "ids": []}
    variants = idle_series_title_variants(canonical)
    keys = {idle_series_title_key(item) for item in variants}
    with connect_db() as conn:
        rows = conn.execute(
            """
            SELECT id, title, series_title, episode_index
            FROM idle_agent_artifacts
            WHERE series_title IS NOT NULL
              AND TRIM(series_title) != ''
            ORDER BY id ASC
            """
        ).fetchall()
    matched: List[sqlite3.Row] = []
    max_episode = 0
    for row in rows:
        row_title = str(row["series_title"] or "")
        if idle_series_title_key(row_title) not in keys:
            continue
        matched.append(row)
        try:
            if row["episode_index"] is not None:
                max_episode = max(max_episode, int(row["episode_index"]))
        except Exception:
            pass
    return {
        "series_title": canonical,
        "total_count": len(matched),
        "max_episode": max_episode,
        "ids": [int(row["id"]) for row in matched],
    }


def idle_custom_prompt_target_reached(prompt: str) -> Dict[str, object]:
    active_prompt = effective_idle_agent_custom_prompt(prompt)
    directive = idle_series_directive_from_prompt(active_prompt)
    target_count = directive.get("target_count")
    series_title = str(directive.get("series_title") or "")
    if not active_prompt or not target_count or not series_title:
        return {"reached": False, "directive": directive, "status": {}}
    status = idle_series_status(series_title)
    reached = int(status.get("max_episode") or 0) >= int(target_count) or int(status.get("total_count") or 0) >= int(target_count)
    return {"reached": reached, "directive": directive, "status": status}


def apply_idle_series_directive_to_plan(plan: Dict[str, object], directive: Dict[str, object]) -> Dict[str, object]:
    series_title = canonical_idle_series_title(directive.get("series_title"))
    target_count = directive.get("target_count")
    if not series_title:
        return plan
    status = idle_series_status(series_title)
    max_episode = int(status.get("max_episode") or 0)
    total_count = int(status.get("total_count") or 0)
    if target_count:
        target_count = int(target_count)
    next_episode = max(max_episode, total_count) + 1
    plan["use_series"] = True
    plan["series_title"] = series_title
    plan["next_episode_index"] = next_episode
    plan["target_episode_count"] = target_count
    if target_count and next_episode >= target_count:
        plan["episode_policy"] = "finale"
        plan["release_prompt_after_this"] = True
    elif str(plan.get("episode_policy") or "").strip() not in {"continue", "new", "finale"}:
        plan["episode_policy"] = "continue" if max_episode or total_count else "new"
    if not str(plan.get("reason") or "").strip():
        plan["reason"] = "用户创作 prompt 明确要求连续系列，系统使用规范系列名和连续编号。"
    return plan


def normalize_idle_series_artifact_title(title: str, series_title: str, episode_index: Optional[int], title_idea: str = "") -> str:
    clean_title = normalize_idle_artifact_terms(str(title or "")).strip()
    clean_title = canonical_idle_series_title(clean_title) or clean_title
    canonical_series = canonical_idle_series_title(series_title)
    idea = normalize_idle_artifact_terms(str(title_idea or "")).strip()
    if canonical_series:
        clean_title = clean_title.replace(f"《{canonical_series}》", "").replace(canonical_series, "")
    clean_title = re.sub(r"^\s*[·:：,，。\\-—]*\s*", "", clean_title)
    clean_title = re.sub(r"^第\s*[0-9０-９一二两三四五六七八九十百]+\s*[集篇章回]\s*[：:·、\\-—]*\s*", "", clean_title)
    if not clean_title or clean_title in {"未命名成果", "未命名"}:
        clean_title = idea
    clean_title = normalize_idle_artifact_terms(clean_title).strip(" ：:，,。；;《》\"'")
    if episode_index is not None and canonical_series:
        suffix = clean_title or f"第{int(episode_index)}篇"
        return f"《{canonical_series}》第{int(episode_index)}篇：{suffix}"
    return clean_title or canonical_series or "未命名成果"


def idle_agent_decision_needs_repair(decision: Dict[str, object]) -> bool:
    title = normalize_idle_artifact_terms(str(decision.get("title") or "")).strip()
    summary = normalize_idle_artifact_terms(str(decision.get("summary") or "")).strip()
    content = normalize_idle_artifact_terms(str(decision.get("content") or "")).strip()
    if not content:
        return False
    if title == UNNAMED_IDLE_ARTIFACT_TITLE:
        return True
    if summary == MALFORMED_IDLE_ARTIFACT_SUMMARY:
        return True
    return False


def create_idle_agent_run(task_type: str, title: str, prompt_summary: str, status: str = "running") -> int:
    now = utc_now()
    with connect_db() as conn:
        cur = conn.execute(
            """
            INSERT INTO idle_agent_runs (
                task_type, title, prompt_summary, status,
                started_at, updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (task_type or "other", title or "未命名任务", prompt_summary, status, now, now),
        )
        return int(cur.lastrowid)


def finish_idle_agent_run(run_id: int, status: str, interrupted_reason: str = "") -> None:
    now = utc_now()
    with connect_db() as conn:
        conn.execute(
            """
            UPDATE idle_agent_runs
            SET status = ?, interrupted_reason = ?, finished_at = ?, updated_at = ?
            WHERE id = ?
            """,
            (status, interrupted_reason or None, now, now, int(run_id)),
        )


def update_idle_agent_run_status(
    run_id: int,
    status: str,
    title: str = "",
    task_type: str = "",
    interrupted_reason: str = "",
) -> None:
    now = utc_now()
    assignments = ["status = ?", "updated_at = ?"]
    params: List[object] = [status, now]
    if title:
        assignments.append("title = ?")
        params.append(title)
    if task_type:
        assignments.append("task_type = ?")
        params.append(task_type)
    if interrupted_reason:
        assignments.append("interrupted_reason = ?")
        params.append(interrupted_reason)
    params.append(int(run_id))
    with connect_db() as conn:
        conn.execute(
            f"UPDATE idle_agent_runs SET {', '.join(assignments)} WHERE id = ?",
            tuple(params),
        )


