def memory_dedupe_agent_is_running() -> bool:
    acquired = MEMORY_DEDUPE_AGENT_WORKER_LOCK.acquire(blocking=False)
    if acquired:
        MEMORY_DEDUPE_AGENT_WORKER_LOCK.release()
        return False
    return True


def memory_refine_agent_is_running() -> bool:
    acquired = MEMORY_REFINE_AGENT_WORKER_LOCK.acquire(blocking=False)
    if acquired:
        MEMORY_REFINE_AGENT_WORKER_LOCK.release()
        return False
    return True


def idle_write_agent_is_running() -> bool:
    acquired = IDLE_AGENT_WORKER_LOCK.acquire(blocking=False)
    if acquired:
        IDLE_AGENT_WORKER_LOCK.release()
        return False
    return True


def current_idle_write_progress() -> Dict[str, object]:
    with connect_db() as conn:
        row = conn.execute(
            """
            SELECT id, status, title, task_type, interrupted_reason, started_at, finished_at, updated_at
            FROM idle_agent_runs
            ORDER BY id DESC
            LIMIT 1
            """
        ).fetchone()
    if row:
        progress = idle_agent_progress_from_status(str(row["status"] or ""), str(row["interrupted_reason"] or ""))
        progress.update(
            {
                "run_id": int(row["id"]),
                "title": str(row["title"] or ""),
                "task_type": str(row["task_type"] or ""),
                "started_at": str(row["started_at"] or ""),
                "finished_at": str(row["finished_at"] or "") if row["finished_at"] else None,
                "updated_at": str(row["updated_at"] or ""),
            }
        )
        return progress
    can_run, reason = idle_agent_can_run(force=False)
    progress = idle_agent_progress_from_reason("idle" if can_run else reason)
    progress["task"] = "idle_write"
    return progress

def current_idle_agent_progress() -> Dict[str, object]:
    watchdog = idle_worker_watchdog_status()
    with connect_db() as conn:
        row = conn.execute(
            """
            SELECT id, status, title, task_type, interrupted_reason, started_at, finished_at, updated_at
            FROM idle_agent_runs
            ORDER BY id DESC
            LIMIT 1
            """
        ).fetchone()
    if row and str(row["status"] or "").lower() in {"running", "writing", "polishing"}:
        progress = idle_agent_progress_from_status(str(row["status"] or ""), str(row["interrupted_reason"] or ""))
        progress.update(
            {
                "run_id": int(row["id"]),
                "title": str(row["title"] or ""),
                "task_type": str(row["task_type"] or ""),
                "started_at": str(row["started_at"] or ""),
                "finished_at": str(row["finished_at"] or "") if row["finished_at"] else None,
                "updated_at": str(row["updated_at"] or ""),
                "watchdog": watchdog,
            }
        )
        return progress
    if memory_dedupe_agent_is_running():
        return {"stage": "memory_dedupe", "label": "记忆去重中", "percent": 45, "task": "memory_dedupe", "watchdog": watchdog}
    if memory_refine_agent_is_running():
        return {"stage": "memory_refine", "label": "记忆精简中", "percent": 48, "task": "memory_refine", "watchdog": watchdog}
    if memory_agent_is_running():
        return {"stage": "memory_agent", "label": "记忆整理中", "percent": 38, "task": "memory_agent", "watchdog": watchdog}
    if idle_write_agent_is_running():
        return {"stage": "writing", "label": "撰写中", "percent": 52, "task": "idle_write", "watchdog": watchdog}
    can_run, reason = idle_agent_can_run(force=False)
    progress = idle_agent_progress_from_reason("idle" if can_run else reason)
    progress["task"] = "idle_worker"
    progress["watchdog"] = watchdog
    if row and progress.get("stage") == "waiting":
        progress.update(
            {
                "last_run_id": int(row["id"]),
                "last_status": str(row["status"] or ""),
                "last_updated_at": str(row["updated_at"] or ""),
            }
        )
    return progress


def list_idle_worker_activity(limit: int = 20, offset: int = 0) -> List[Dict[str, object]]:
    event_types = {
        "idle_worker_tick",
        "idle_worker_tick_done",
        "idle_worker_skip",
        "idle_worker_error",
        "warning_idle_worker_watchdog",
        "opening_cache_idle_refresh",
        "opening_cache_refresh_error",
        "memory_dedupe_agent_run",
        "memory_dedupe_agent_error",
        "memory_refine_agent_run",
        "memory_refine_agent_error",
        "idle_agent_artifact_created",
        "idle_agent_error",
    }
    placeholders = ",".join("?" for _ in event_types)
    max_rows = min(max(int(limit), 1), 501)
    start_row = max(int(offset), 0)
    with connect_db() as conn:
        rows = conn.execute(
            f"""
            SELECT id, event_type, visitor_ip, created_at, metadata_json
            FROM events
            WHERE event_type IN ({placeholders})
            ORDER BY datetime(created_at) DESC, id DESC
            LIMIT ? OFFSET ?
            """,
            (*sorted(event_types), max_rows, start_row),
        ).fetchall()
    return [
        {
            "id": int(row["id"]),
            "event_type": str(row["event_type"]),
            "visitor_ip": str(row["visitor_ip"] or "local"),
            "created_at": str(row["created_at"] or ""),
            "updated_at": str(row["created_at"] or ""),
            "metadata": parse_event_metadata(str(row["metadata_json"] or "{}")),
        }
        for row in rows
    ]


def recent_device_identities_for_opening_cache(limit: int = IDLE_OPENING_CACHE_REFRESH_LIMIT) -> List[str]:
    with connect_db() as conn:
        rows = conn.execute(
            """
            SELECT visitor_ip, MAX(updated_at) AS latest
            FROM curated_memories
            WHERE visitor_ip LIKE 'device:%'
            GROUP BY visitor_ip
            ORDER BY datetime(latest) DESC
            LIMIT ?
            """,
            (max(1, int(limit)),),
        ).fetchall()
    return [str(row["visitor_ip"] or "") for row in rows if is_device_identity(str(row["visitor_ip"] or ""))]


def opening_cache_fixed_refresh_slot(now: Optional[datetime] = None) -> str:
    hours = tuple(IDLE_OPENING_CACHE_FIXED_REFRESH_HOURS)
    if not hours:
        return ""
    tz = local_timezone()
    current = now or datetime.now(tz)
    if current.tzinfo is None:
        current = current.replace(tzinfo=tz)
    else:
        current = current.astimezone(tz)

    due_hours = [hour for hour in hours if current.hour >= hour]
    slot_date = current.date()
    slot_hour = due_hours[-1] if due_hours else hours[-1]
    if not due_hours:
        slot_date = (current - timedelta(days=1)).date()
    return f"{slot_date.isoformat()}T{slot_hour:02d}:00{current.strftime('%z')}"


def run_opening_cache_refresh_once(force: bool = False) -> Dict[str, object]:
    started_at = utc_now()
    started = time.perf_counter()
    fixed_slot = opening_cache_fixed_refresh_slot()
    fixed_due = bool(fixed_slot) and get_app_setting("idle_opening_cache_fixed_refresh_slot", "") != fixed_slot
    if not force:
        last = get_app_setting("idle_opening_cache_refresh_last_at", "")
        age = iso_seconds_ago(last) if last else None
        if not fixed_due and age is not None and age < IDLE_OPENING_CACHE_REFRESH_INTERVAL_SECONDS:
            return {"status": "skipped", "reason": "recent_prompt_cache", "started_at": started_at, "duration_ms": 0.0}
    try:
        devices = recent_device_identities_for_opening_cache()
        refreshed = 0
        for device_id in devices:
            refresh_cached_opening_prompt(device_id)
            refreshed += 1
        set_app_setting("idle_opening_cache_refresh_last_at", utc_now())
        if fixed_due:
            set_app_setting("idle_opening_cache_fixed_refresh_slot", fixed_slot)
        duration_ms = round((time.perf_counter() - started) * 1000, 3)
        result = {
            "status": "completed" if refreshed else "skipped",
            "reason": "fixed_schedule_refreshed" if fixed_due and refreshed else ("refreshed" if refreshed else "no_devices"),
            "device_count": refreshed,
            "refreshed_devices": devices[:10],
            "fixed_refresh_slot": fixed_slot if fixed_due else "",
            "started_at": started_at,
            "duration_ms": duration_ms,
        }
        record_event(None, "opening_cache_idle_refresh", "local", result)
        return result
    except Exception as exc:
        duration_ms = round((time.perf_counter() - started) * 1000, 3)
        result = {"status": "failed", "reason": "error", "error": str(exc), "started_at": started_at, "duration_ms": duration_ms}
        record_event(None, "opening_cache_refresh_error", "local", result)
        return result


def artifact_memory_text(
    artifact_id: int,
    title: str,
    artifact_type: str,
    content: str,
    series_title: str = "",
    episode_index: Optional[int] = None,
    summary: str = "",
) -> str:
    clean_title = normalize_idle_artifact_terms(title).strip()
    clean_type = normalize_idle_artifact_terms(artifact_type).strip()
    clean_content = normalize_idle_artifact_content_text(content)
    clean_summary = normalize_idle_artifact_terms(summary)
    series = normalize_idle_artifact_terms(series_title).strip()
    episode_text = f"第 {int(episode_index)} 集" if episode_index is not None else ""
    short_summary = clean_summary.strip() or compact_idle_artifact_content(clean_content, 220)
    parts = [
        f"作品记忆：已创作成果 #{artifact_id}《{clean_title or '未命名成果'}》。",
        f"类型：{clean_type or 'other'}。",
    ]
    if series:
        parts.append(f"系列：{series}。")
    if episode_text:
        parts.append(f"进度：{episode_text}。")
    if short_summary:
        parts.append(f"摘要：{short_summary}")
    return "".join(parts)


def create_artifact_memory(
    artifact_id: int,
    title: str,
    artifact_type: str,
    content: str,
    series_title: str = "",
    episode_index: Optional[int] = None,
    summary: str = "",
) -> int:
    text = artifact_memory_text(
        artifact_id,
        title,
        artifact_type,
        content,
        series_title=series_title,
        episode_index=episode_index,
        summary=summary,
    )
    memory_id = save_curated_memory(
        source_session_id=f"artifact-{int(artifact_id)}",
        start_message_id=int(artifact_id),
        end_message_id=int(artifact_id),
        content=text,
        importance_label="artifact",
        confidence=0.85,
    )
    vector = embedding_client.embed_text(text)
    upsert_curated_memory_vector(memory_id, vector, embedding_client.EMBEDDING_MODEL)
    return memory_id


PREQUEL_ARTIFACT_MARKERS = (
    "前传",
    "外传",
    "番外",
    "起源",
    "过去篇",
    "特别篇",
    "origin",
    "prequel",
)


def is_prequel_idle_artifact(title: str, content: str = "") -> bool:
    text = f"{title}\n{content}".lower()
    return any(marker.lower() in text for marker in PREQUEL_ARTIFACT_MARKERS)


def current_series_mainline_episode(series_title: str) -> int:
    clean_series = normalize_idle_artifact_terms(series_title).strip()
    if not clean_series:
        return 0
    with connect_db() as conn:
        row = conn.execute(
            """
            SELECT MAX(episode_index) AS max_episode
            FROM idle_agent_artifacts
            WHERE series_title = ?
              AND episode_index IS NOT NULL
            """,
            (clean_series,),
        ).fetchone()
    return int(row["max_episode"] or 0) if row else 0


def resolve_idle_series_episode_index(
    series_title: str,
    requested_episode: object,
    title: str = "",
    content: str = "",
) -> Optional[int]:
    clean_series = normalize_idle_artifact_terms(series_title).strip()
    if not clean_series:
        return None
    if is_prequel_idle_artifact(title, content):
        return None
    current_episode = current_series_mainline_episode(clean_series)
    next_episode = current_episode + 1
    try:
        requested = int(requested_episode) if requested_episode not in (None, "", "null") else None
    except Exception:
        requested = None
    if requested == next_episode:
        return requested
    return next_episode


def renumber_idle_series_mainline_episodes(series_title: str) -> Dict[str, int]:
    clean_series = normalize_idle_artifact_terms(series_title).strip()
    if not clean_series:
        return {"updated": 0}
    updated_ids: List[int] = []
    with connect_db() as conn:
        rows = conn.execute(
            """
            SELECT id
            FROM idle_agent_artifacts
            WHERE series_title = ?
              AND episode_index IS NOT NULL
            ORDER BY created_at ASC, id ASC
            """,
            (clean_series,),
        ).fetchall()
        updated = 0
        for index, row in enumerate(rows, start=1):
            cur = conn.execute(
                """
                UPDATE idle_agent_artifacts
                SET episode_index = ?
                WHERE id = ?
                  AND COALESCE(episode_index, -1) != ?
                """,
                (index, int(row["id"]), index),
            )
            if cur.rowcount:
                updated += int(cur.rowcount or 0)
                updated_ids.append(int(row["id"]))
    reindexed = 0
    for artifact_id in updated_ids:
        try:
            index_idle_agent_artifact(artifact_id)
            reindexed += 1
        except Exception as exc:
            record_event(None, "idle_artifact_index_error", "local", {
                "artifact_id": artifact_id,
                "error": str(exc),
            })
    return {"updated": updated, "reindexed": reindexed, "total": len(rows)}


def save_idle_agent_artifact(
    run_id: int,
    title: str,
    artifact_type: str,
    content: str,
    series_title: str = "",
    episode_index: Optional[int] = None,
    summary: str = "",
) -> int:
    clean_title = normalize_idle_artifact_terms(title)
    clean_series = normalize_idle_artifact_terms(series_title)
    clean_summary = normalize_idle_artifact_terms(summary)
    text = normalize_idle_artifact_content_text(content).strip()
    clean_type = normalize_artifact_type(artifact_type, clean_title, text)
    if not text:
        raise ValueError("idle artifact content is empty")
    artifact_id = 0
    series_value = clean_series.strip() or None
    episode_value = resolve_idle_series_episode_index(
        series_value or "",
        episode_index,
        title=clean_title,
        content=text,
    )
    summary_value = clean_summary.strip() or compact_idle_artifact_content(text, 260)
    with connect_db() as conn:
        cur = conn.execute(
            """
            INSERT INTO idle_agent_artifacts (
                run_id, title, artifact_type, content,
                series_title, episode_index, summary, created_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(run_id),
                clean_title.strip() or "未命名成果",
                clean_type or "other",
                text,
                series_value,
                episode_value,
                summary_value,
                utc_now(),
            ),
        )
        artifact_id = int(cur.lastrowid)
    try:
        index_idle_agent_artifact(artifact_id)
    except Exception as exc:
        record_event(None, "idle_artifact_index_error", "local", {
            "artifact_id": artifact_id,
            "error": str(exc),
        })
    return artifact_id


def compact_idle_artifact_content(content: str, max_chars: int) -> str:
    text = " ".join(content.strip().split())
    if not text:
        return ""
    pieces = re.split(r"(?<=[。！？.!?])\s*", text)
    seen = set()
    selected: List[str] = []
    total = 0
    for piece in pieces:
        clean = piece.strip()
        if not clean:
            continue
        key = clean[:120]
        if key in seen:
            continue
        seen.add(key)
        if total + len(clean) > max_chars and selected:
            break
        selected.append(clean)
        total += len(clean)
    body = "".join(selected).strip() if selected else text
    if len(body) > max_chars:
        body = body[:max_chars].rstrip() + "..."
    return body


def load_idle_artifact_term_replacements() -> Dict[str, str]:
    replacements: Dict[str, str] = {}
    replacements.update(DEFAULT_IDLE_ARTIFACT_TERM_REPLACEMENTS)

    def merge_payload(payload: object) -> None:
        if not isinstance(payload, dict):
            return
        for source, target in payload.items():
            source_text = str(source).strip()
            target_text = str(target).strip()
            if source_text and target_text:
                replacements[source_text] = target_text

    if IDLE_ARTIFACT_TERM_REPLACEMENTS_FILE:
        try:
            payload = json.loads(Path(IDLE_ARTIFACT_TERM_REPLACEMENTS_FILE).read_text(encoding="utf-8"))
            merge_payload(payload)
        except Exception:
            pass
    if IDLE_ARTIFACT_TERM_REPLACEMENTS:
        try:
            payload = json.loads(IDLE_ARTIFACT_TERM_REPLACEMENTS)
            merge_payload(payload)
        except Exception:
            pass
    return replacements


def replace_idle_artifact_terms(text: str, replacements: Dict[str, str]) -> str:
    if not isinstance(text, str):
        return ""
    normalized = text
    for source, target in sorted(replacements.items(), key=lambda item: len(item[0]), reverse=True):
        normalized = re.sub(re.escape(source), target, normalized, flags=re.I)
    return normalized


def strip_idle_artifact_unicode_noise(text: str) -> str:
    if not isinstance(text, str):
        return ""
    cleaned = text.replace("\ufffd", "")
    cleaned = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]", "", cleaned)
    for match in re.finditer(r"(?:\\u[0-9a-fA-F]{4}){3,}", cleaned):
        run = match.group(0).lower()
        if "\\ufffd" in run or re.search(r"\\u00(?:0[0-8bcef]|1[0-9a-f]|7f)", run):
            return cleaned[: match.start()].rstrip()
    cleaned = re.sub(r"\\ufffd", "", cleaned, flags=re.I)
    cleaned = re.sub(r"\\u00(?:0[0-8bcef]|1[0-9a-f]|7f)", "", cleaned, flags=re.I)
    return cleaned


def unescape_idle_artifact_markdown_marks(text: str) -> str:
    if not isinstance(text, str):
        return ""
    return re.sub(r"\\+([*_~`#\[\]\(\)>-])", r"\1", text)


def normalize_idle_artifact_terms(text: str) -> str:
    replaced = replace_idle_artifact_terms(text, load_idle_artifact_term_replacements())
    return strip_idle_artifact_unicode_noise(replaced)


def normalize_idle_artifact_content_text(text: str) -> str:
    normalized = normalize_idle_artifact_terms(text)
    return unescape_idle_artifact_markdown_marks(normalized)


class TermReplacementStreamFilter:
    def __init__(self) -> None:
        self.replacements = load_idle_artifact_term_replacements()
        self.keep_chars = max((len(key) for key in self.replacements), default=1) - 1
        self.buffer = ""

    def feed(self, text: str) -> str:
        if not text:
            return ""
        self.buffer += text
        if self.keep_chars <= 0:
            chunk, self.buffer = self.buffer, ""
            return replace_idle_artifact_terms(chunk, self.replacements)
        if len(self.buffer) <= self.keep_chars:
            return ""
        chunk = self.buffer[:-self.keep_chars]
        self.buffer = self.buffer[-self.keep_chars:]
        return replace_idle_artifact_terms(chunk, self.replacements)

    def flush(self) -> str:
        chunk, self.buffer = self.buffer, ""
        return replace_idle_artifact_terms(chunk, self.replacements)


def format_idle_artifact_index_text(
    title: str,
    artifact_type: str,
    content: str,
    series_title: str = "",
    episode_index: Optional[int] = None,
    summary: str = "",
) -> str:
    body = compact_idle_artifact_content(content, 1600)
    series_line = f"系列：{series_title.strip()}\n" if series_title and series_title.strip() else ""
    episode_line = f"集数：{int(episode_index)}\n" if episode_index is not None else ""
    summary_line = f"摘要：{summary.strip()}\n" if summary and summary.strip() else ""
    return (
        f"标题：{title.strip() or '未命名成果'}\n"
        f"类型：{artifact_type.strip() or 'other'}\n"
        f"{series_line}"
        f"{episode_line}"
        f"{summary_line}"
        f"内容摘要：{body}"
    )


def index_idle_agent_artifact(artifact_id: int) -> None:
    with connect_db() as conn:
        row = conn.execute(
            """
            SELECT id, title, artifact_type, content, series_title, episode_index, summary
            FROM idle_agent_artifacts
            WHERE id = ?
            """,
            (int(artifact_id),),
        ).fetchone()
    if row is None:
        raise ValueError(f"idle artifact not found: {artifact_id}")

    index_text = format_idle_artifact_index_text(
        str(row["title"]),
        str(row["artifact_type"]),
        str(row["content"]),
        str(row["series_title"] or ""),
        int(row["episode_index"]) if row["episode_index"] is not None else None,
        str(row["summary"] or ""),
    )
    vector = embedding_client.embed_text(index_text)
    upsert_idle_artifact_vector(int(row["id"]), vector, embedding_client.EMBEDDING_MODEL, index_text)


def upsert_idle_artifact_vector(
    artifact_id: int,
    vector: object,
    model_name: str,
    index_text: str,
) -> None:
    arr = vector_memory.normalize_vector(vector)
    with connect_db() as conn:
        conn.execute(
            """
            INSERT INTO idle_artifact_vectors (
                artifact_id, dim, vector, model_name, index_text, created_at
            )
            VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(artifact_id) DO UPDATE SET
                dim = excluded.dim,
                vector = excluded.vector,
                model_name = excluded.model_name,
                index_text = excluded.index_text,
                created_at = excluded.created_at
            """,
            (
                int(artifact_id),
                int(arr.shape[0]),
                arr.tobytes(),
                model_name,
                index_text,
                utc_now(),
            ),
        )


def retrieve_idle_artifacts(query_vector: object) -> List[Dict[str, object]]:
    query = vector_memory.normalize_vector(query_vector)
    with connect_db() as conn:
        rows = conn.execute(
            """
            SELECT a.id, a.title, a.artifact_type, a.content,
                   a.series_title, a.episode_index, a.summary, a.created_at,
                   v.dim, v.vector, v.model_name
            FROM idle_agent_artifacts a
            JOIN idle_artifact_vectors v ON v.artifact_id = a.id
            ORDER BY a.id ASC
            """
        ).fetchall()

    scored: List[Dict[str, object]] = []
    for row in rows:
        vector = vector_memory.blob_to_vector(row["vector"], int(row["dim"]))
        if vector.shape != query.shape:
            continue
        score = float(vector.dot(query))
        if score < IDLE_ARTIFACT_MIN_SCORE:
            continue
        scored.append(
            {
                "id": int(row["id"]),
                "title": str(row["title"]),
                "artifact_type": str(row["artifact_type"]),
                "content": str(row["content"]),
                "series_title": str(row["series_title"] or ""),
                "episode_index": int(row["episode_index"]) if row["episode_index"] is not None else None,
                "summary": str(row["summary"] or ""),
                "created_at": str(row["created_at"]),
                "score": score,
            }
        )
    scored.sort(key=lambda item: (-float(item["score"]), int(item["id"])))
    return scored[:IDLE_ARTIFACT_TOP_K]


def format_idle_artifact_context(artifacts: List[Dict[str, object]]) -> str:
    if not artifacts:
        return ""
    lines = [
        "以下是模型空闲时创作过的成果，仅在当前话题相关时参考。",
        "不要强行复述作品；可以用它们作为设定、角色、风格或前文创作的线索。",
        "",
    ]
    for index, item in enumerate(artifacts, start=1):
        content = str(item.get("summary") or "").strip()
        if not content:
            content = compact_idle_artifact_content(str(item["content"]), IDLE_ARTIFACT_CONTEXT_CHARS)
        lines.append(
            f"[空闲创作成果 {index}] score={float(item['score']):.3f} "
            f"type={item['artifact_type']} title={item['title']} "
            f"series={item.get('series_title') or '-'} episode={item.get('episode_index') or '-'}"
        )
        lines.append(content)
        lines.append("")
    return "\n".join(lines).strip()


def backfill_idle_artifact_vectors(limit: int = 10000) -> Dict[str, int]:
    max_rows = min(max(int(limit), 1), 100000)
    with connect_db() as conn:
        rows = conn.execute(
            """
            SELECT a.id
            FROM idle_agent_artifacts a
            LEFT JOIN idle_artifact_vectors v ON v.artifact_id = a.id
            WHERE v.artifact_id IS NULL
            ORDER BY a.id ASC
            LIMIT ?
            """,
            (max_rows,),
        ).fetchall()

    indexed = 0
    failed = 0
    for row in rows:
        try:
            index_idle_agent_artifact(int(row["id"]))
            indexed += 1
        except Exception:
            failed += 1
    return {"indexed": indexed, "failed": failed}


def load_idle_series_context(
    max_series: int = IDLE_SERIES_CONTEXT_MAX_SERIES,
    max_episodes: int = IDLE_SERIES_CONTEXT_MAX_EPISODES,
) -> List[Dict[str, object]]:
    series_limit = min(max(int(max_series), 1), 12)
    episode_limit = min(max(int(max_episodes), 1), 8)
    with connect_db() as conn:
        series_rows = conn.execute(
            """
            SELECT series_title,
                   COUNT(*) AS total_count,
                   MAX(COALESCE(episode_index, 0)) AS max_episode,
                   MAX(id) AS newest_id
            FROM idle_agent_artifacts
            WHERE series_title IS NOT NULL
              AND TRIM(series_title) != ''
            GROUP BY series_title
            ORDER BY newest_id DESC
            LIMIT ?
            """,
            (series_limit,),
        ).fetchall()
        contexts: List[Dict[str, object]] = []
        for row in series_rows:
            series_title = str(row["series_title"])
            episode_rows = conn.execute(
                """
                SELECT id, title, episode_index, summary, content, created_at
                FROM idle_agent_artifacts
                WHERE series_title = ?
                ORDER BY
                    CASE WHEN episode_index IS NULL THEN 1 ELSE 0 END,
                    episode_index DESC,
                    id DESC
                LIMIT ?
                """,
                (series_title, episode_limit),
            ).fetchall()
            episode_items = [row_to_dict(item) for item in episode_rows]
            episode_items.sort(
                key=lambda item: (
                    1 if item.get("episode_index") is None else 0,
                    int(item.get("episode_index") or 0),
                    int(item.get("id") or 0),
                )
            )
            contexts.append(
                {
                    "series_title": series_title,
                    "total_count": int(row["total_count"] or 0),
                    "max_episode": int(row["max_episode"] or 0),
                    "episodes": episode_items,
                }
            )
    return contexts


def load_idle_series_catalog(limit: int = IDLE_SERIES_PLANNER_MAX_CATALOG) -> List[Dict[str, object]]:
    max_rows = max(1, min(int(limit), 200))
    with connect_db() as conn:
        series_rows = conn.execute(
            """
            SELECT series_title,
                   COUNT(*) AS total_count,
                   MAX(COALESCE(episode_index, 0)) AS max_episode,
                   MAX(id) AS newest_id
            FROM idle_agent_artifacts
            WHERE series_title IS NOT NULL
              AND TRIM(series_title) != ''
            GROUP BY series_title
            ORDER BY newest_id DESC
            LIMIT ?
            """,
            (max_rows,),
        ).fetchall()
        catalog: List[Dict[str, object]] = []
        for row in series_rows:
            title = str(row["series_title"] or "").strip()
            latest = conn.execute(
                """
                SELECT id, title, summary, created_at
                FROM idle_agent_artifacts
                WHERE series_title = ?
                ORDER BY id DESC
                LIMIT 1
                """,
                (title,),
            ).fetchone()
            catalog.append(
                {
                    "series_title": title,
                    "total_count": int(row["total_count"] or 0),
                    "max_episode": int(row["max_episode"] or 0),
                    "newest_id": int(row["newest_id"] or 0),
                    "latest_title": str(latest["title"] or "") if latest else "",
                    "latest_summary": str(latest["summary"] or "") if latest else "",
                    "latest_created_at": str(latest["created_at"] or "") if latest else "",
                }
            )
    return catalog


def idle_series_candidate_titles(custom_prompt: str, catalog: List[Dict[str, object]]) -> List[str]:
    focus = normalize_idle_artifact_terms(custom_prompt or "")
    quoted_titles = [item.strip() for item in re.findall(r"《([^》]{1,120})》", focus) if item.strip()]
    directive = idle_series_directive_from_prompt(focus)
    selected: List[str] = []

    def add(title: str) -> None:
        clean = canonical_idle_series_title(title)
        if clean and clean not in selected:
            selected.append(clean)

    if directive.get("explicit_series"):
        add(str(directive.get("series_title") or ""))
    for item in catalog:
        title = str(item.get("series_title") or "").strip()
        if not title:
            continue
        canonical = canonical_idle_series_title(title)
        if canonical in focus or any(quoted and (quoted in canonical or canonical in quoted) for quoted in quoted_titles):
            add(title)
    return selected[: max(1, IDLE_SERIES_PLANNER_MAX_FULL_SERIES)]


def load_complete_idle_series_works(series_titles: List[str]) -> Dict[str, List[Dict[str, object]]]:
    result: Dict[str, List[Dict[str, object]]] = {}
    clean_titles = [canonical_idle_series_title(item) for item in series_titles if str(item or "").strip()]
    if not clean_titles:
        return result
    with connect_db() as conn:
        for title in clean_titles:
            variants = idle_series_title_variants(title) or [title]
            in_clause, params = sql_in_clause_params(variants)
            rows = conn.execute(
                f"""
                SELECT id, title, artifact_type, series_title, episode_index, summary, content, created_at
                FROM idle_agent_artifacts
                WHERE series_title IN {in_clause}
                   OR series_title LIKE ?
                   OR (TRIM(COALESCE(series_title, '')) = '' AND title LIKE ?)
                ORDER BY
                    CASE WHEN episode_index IS NULL THEN 1 ELSE 0 END,
                    COALESCE(episode_index, id) ASC,
                    id ASC
                """,
                (*params, f"{title}·%", f"%{title}%"),
            ).fetchall()
            result[title] = [row_to_dict(row) for row in rows]
    return result


def format_complete_idle_series_works(series_works: Dict[str, List[Dict[str, object]]]) -> str:
    if not series_works:
        return "无完整系列正文。"
    lines = [
        "同系列全部前序作品：",
        "以下内容供剧情规划 agent 阅读并分析发展状况；如果本轮不续写对应系列，不要把这些旧作品当成写作任务。",
    ]
    for series_title, rows in series_works.items():
        lines.append("")
        lines.append(f"## 系列《{series_title}》：共 {len(rows)} 篇")
        for row in rows:
            episode_index = row.get("episode_index")
            episode = f"第 {int(episode_index)} 集" if episode_index is not None else "前传/番外/外传/独立篇"
            lines.append("")
            lines.append(f"### {episode} #{row.get('id')}《{row.get('title') or '未命名成果'}》")
            if row.get("summary"):
                lines.append(f"摘要：{row.get('summary')}")
            lines.append(f"正文：{row.get('content') or ''}")
    return "\n".join(lines).strip()


def build_idle_series_planner_context(
    custom_prompt: str,
    catalog: List[Dict[str, object]],
    series_works: Dict[str, List[Dict[str, object]]],
) -> str:
    lines = [
        "用户配置创作 prompt：",
        custom_prompt.strip() or "（无）",
        "",
        "可用系列目录：",
    ]
    if catalog:
        for item in catalog:
            lines.append(
                f"- 《{item['series_title']}》 total={item['total_count']} "
                f"max_episode={item['max_episode']} newest=#{item['newest_id']} "
                f"latest={item['latest_title'] or '未命名'} summary={item['latest_summary'] or ''}"
            )
    else:
        lines.append("（当前没有已登记系列）")
    lines.append("")
    lines.append(format_complete_idle_series_works(series_works))
    return "\n".join(lines).strip()


def default_idle_series_plan(reason: str = "") -> Dict[str, object]:
    return {
        "use_series": False,
        "series_title": "",
        "episode_policy": "new",
        "next_episode_index": None,
        "target_episode_count": None,
        "release_prompt_after_this": False,
        "title_idea": "",
        "intent": "",
        "must_obey": [],
        "candidate_characters": [],
        "setting_plan": "",
        "beats": [],
        "anti_repetition_strategy": "",
        "image_plan_brief": "",
        "reason": reason,
    }


def parse_idle_series_planner_response(text: str) -> Dict[str, object]:
    cleaned = str(text or "").strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(?:json)?\s*", "", cleaned)
        cleaned = re.sub(r"\s*```$", "", cleaned)
    candidates = [cleaned]
    match = re.search(r"\{.*\}", cleaned, flags=re.S)
    if match:
        candidates.append(match.group(0))
    for candidate in candidates:
        try:
            payload = json.loads(candidate, strict=False)
        except Exception:
            continue
        if isinstance(payload, dict):
            plan = default_idle_series_plan()
            plan.update(
                {
                    "use_series": bool(payload.get("use_series")),
                    "series_title": normalize_idle_artifact_terms(str(payload.get("series_title") or "")).strip(),
                    "episode_policy": str(payload.get("episode_policy") or "new").strip() or "new",
                    "release_prompt_after_this": bool(payload.get("release_prompt_after_this")),
                    "title_idea": str(payload.get("title_idea") or "").strip(),
                    "intent": str(payload.get("intent") or "").strip(),
                    "setting_plan": str(payload.get("setting_plan") or "").strip(),
                    "anti_repetition_strategy": str(payload.get("anti_repetition_strategy") or "").strip(),
                    "image_plan_brief": str(payload.get("image_plan_brief") or "").strip(),
                    "reason": str(payload.get("reason") or "").strip(),
                }
            )
            try:
                plan["next_episode_index"] = (
                    int(payload.get("next_episode_index"))
                    if payload.get("next_episode_index") not in (None, "", "null")
                    else None
                )
            except Exception:
                plan["next_episode_index"] = None
            try:
                plan["target_episode_count"] = (
                    int(payload.get("target_episode_count"))
                    if payload.get("target_episode_count") not in (None, "", "null")
                    else None
                )
            except Exception:
                plan["target_episode_count"] = None
            for key in ("must_obey", "candidate_characters", "beats"):
                value = payload.get(key)
                if isinstance(value, list):
                    plan[key] = [str(item).strip() for item in value if str(item).strip()]
                elif isinstance(value, str) and value.strip():
                    plan[key] = [value.strip()]
            return plan
    return default_idle_series_plan("planner_invalid_json")


def call_idle_series_planner_model(context: str) -> Dict[str, object]:
    client, http_client, model_slot = openai_client_for_slot(MODEL_SLOT_BACKGROUND, timeout=IDLE_SERIES_PLANNER_TIMEOUT)
    try:
        resp = client.chat.completions.create(
            **model_completion_kwargs(model_slot),
            messages=[
                {"role": "system", "content": IDLE_SERIES_PLANNER_SYSTEM_PROMPT},
                {"role": "user", "content": context},
            ],
            temperature=IDLE_SERIES_PLANNER_TEMPERATURE,
            top_p=IDLE_SERIES_PLANNER_TOP_P,
            max_tokens=IDLE_SERIES_PLANNER_MAX_TOKENS,
        )
        _, answer = split_think_text(resp.choices[0].message.content or "")
        return parse_idle_series_planner_response(answer)
    finally:
        http_client.close()


def idle_series_plan_for_prompt(custom_prompt: str) -> Dict[str, object]:
    if not IDLE_SERIES_PLANNER_ENABLED or not custom_prompt.strip():
        return default_idle_series_plan("no_custom_prompt")
    directive = idle_series_directive_from_prompt(custom_prompt)
    target_count = directive.get("target_count")
    directive_title = canonical_idle_series_title(directive.get("series_title"))
    if directive_title and target_count:
        status = idle_series_status(directive_title)
        if int(status.get("max_episode") or 0) >= int(target_count) or int(status.get("total_count") or 0) >= int(target_count):
            plan = default_idle_series_plan("series_target_reached")
            plan.update(
                {
                    "use_series": False,
                    "series_title": directive_title,
                    "target_episode_count": int(target_count),
                    "release_prompt_after_this": True,
                    "reason": f"系列《{directive_title}》已达到用户要求的 {int(target_count)} 篇，停止继续写作该 prompt。",
                }
            )
            record_event(None, "idle_series_planner_result", "local", {"candidate_series": [directive_title], "plan": plan})
            return plan
    catalog = load_idle_series_catalog()
    candidate_titles = idle_series_candidate_titles(custom_prompt, catalog)
    series_works = load_complete_idle_series_works(candidate_titles)
    context = build_idle_series_planner_context(custom_prompt, catalog, series_works)
    try:
        plan = call_idle_series_planner_model(context)
    except Exception as exc:
        plan = default_idle_series_plan(f"planner_error: {exc}")
        record_event(None, "idle_series_planner_error", "local", {"error": str(exc)})
    if plan.get("use_series") and not plan.get("series_title") and candidate_titles:
        plan["series_title"] = candidate_titles[0]
    planned_title = str(plan.get("series_title") or "").strip()
    if plan.get("use_series") and planned_title and planned_title not in series_works:
        series_works = load_complete_idle_series_works([planned_title])
        context = build_idle_series_planner_context(custom_prompt, catalog, series_works)
        try:
            plan = call_idle_series_planner_model(context)
            if plan.get("use_series") and not plan.get("series_title"):
                plan["series_title"] = planned_title
        except Exception as exc:
            record_event(None, "idle_series_planner_second_pass_error", "local", {"error": str(exc), "series_title": planned_title})
    if directive.get("explicit_series"):
        plan = apply_idle_series_directive_to_plan(plan, directive)
    record_event(
        None,
        "idle_series_planner_result",
        "local",
        {
            "candidate_series": candidate_titles,
            "plan": plan,
        },
    )
    return plan


def format_idle_series_plan_context(plan: Dict[str, object]) -> str:
    if not plan or str(plan.get("reason") or "") == "no_custom_prompt":
        return ""
    if not plan.get("use_series") and str(plan.get("reason") or "").startswith(("planner_error", "planner_invalid")):
        return ""
    lines = [
        "剧情规划 agent 结果：",
        f"use_series={bool(plan.get('use_series'))}",
        f"series_title={plan.get('series_title') or ''}",
        f"episode_policy={plan.get('episode_policy') or 'new'}",
        f"next_episode_index={plan.get('next_episode_index')}",
        f"target_episode_count={plan.get('target_episode_count')}",
        f"release_prompt_after_this={bool(plan.get('release_prompt_after_this'))}",
    ]
    if plan.get("use_series") and plan.get("series_title"):
        lines.extend(
            [
                "系列命名与编号硬约束：",
                f"- series_title 必须精确输出为：{plan.get('series_title')}",
                "- 不要给 series_title 增减书名号、空格、副标题、Dating/日记/观察等别名。",
                "- title 可以有本集副标题，但必须服从规划的 next_episode_index，不要自行重排、跳号或复用旧编号。",
            ]
        )
    for key, label in (
        ("title_idea", "标题方向"),
        ("intent", "表达意图"),
        ("setting_plan", "场景计划"),
        ("anti_repetition_strategy", "结构避重复策略"),
        ("image_plan_brief", "配图方向"),
        ("reason", "规划理由"),
    ):
        value = str(plan.get(key) or "").strip()
        if value:
            lines.append(f"{label}：{value}")
    for key, label in (
        ("must_obey", "必须执行的创作 prompt 要求"),
        ("candidate_characters", "候选出场人物"),
        ("beats", "剧情节拍"),
    ):
        values = [str(item).strip() for item in plan.get(key) or [] if str(item).strip()]
        if values:
            lines.append(f"{label}：")
            for item in values:
                lines.append(f"- {item}")
    return "\n".join(lines).strip()


def format_idle_series_context(series_context: List[Dict[str, object]]) -> str:
    if not series_context:
        return ""
    lines = [
        "已有连续系列资料：",
        "只有在本篇确实需要续写时才使用；不要因为这里出现某个系列就默认续写它。",
        "如果选择续写其中某个系列，必须先承接以下前情；主线 episode_index 只能使用提示中的下一集编号。",
        "前传、番外、起源故事可以丰富人物过去，但 episode_index 必须填 null，避免污染主线编号。",
        "如果不续写某系列，以下资料仅用于避开重复题材、重复场景和重复对白。",
    ]
    for series in series_context:
        title = str(series.get("series_title") or "").strip()
        max_episode = int(series.get("max_episode") or 0)
        next_episode = max_episode + 1
        total_count = int(series.get("total_count") or 0)
        lines.append("")
        lines.append(
            f"系列《{title}》：已有作品 {total_count} 个，主线最大集数 {max_episode}；"
            f"如果续写主线，episode_index 下一集必须填写 {next_episode}。"
        )
        lines.append("近期剧情目录（只用于判断是否真的需要续写；不要模仿这些作品的开场、场景、笑点或句式）：")
        episodes = list(series.get("episodes") or [])
        omitted = max(0, total_count - len(episodes))
        if omitted:
            lines.append(f"- 已省略更早的 {omitted} 条旧摘要，避免旧桥段过度污染本篇。")
        for item in episodes:
            episode_index = item.get("episode_index")
            episode = f"第 {int(episode_index)} 集" if episode_index is not None else "前传/番外"
            summary = str(item.get("summary") or "").strip() or compact_idle_artifact_content(
                str(item.get("content") or ""),
                160,
            )
            lines.append(
                f"- {episode} #{item.get('id')}《{item.get('title') or '未命名成果'}》："
                f"{compact_idle_artifact_content(summary, 90)}"
            )
        recent = episodes[-IDLE_SERIES_CONTEXT_RECENT_CONTENT:]
        if recent:
            lines.append("最近细节片段（用于衔接角色状态和伏笔，不要原样复读）：")
            for item in recent:
                episode_index = item.get("episode_index")
                episode = f"第 {int(episode_index)} 集" if episode_index is not None else "前传/番外"
                content = compact_idle_artifact_content(
                    str(item.get("content") or ""),
                    IDLE_SERIES_CONTEXT_RECENT_CHARS,
                )
                if content:
                    lines.append(f"[{episode} #{item.get('id')}] {content}")
    return "\n".join(lines)


