def idle_recent_repetition_flags_from_rows(rows: List[sqlite3.Row]) -> List[str]:
    repeated_flags: List[str] = []
    for row in rows:
        text = f"{row['title'] or ''}\n{row['summary'] or ''}\n{row['content'] or ''}"
        for phrase in (
            "空气动力学阻力",
            "这种风格的衣服",
            "显影咖啡厅",
            "咖啡厅",
            "理工男",
            "约会实验",
            "非理性偏差实验",
            "城市心跳",
            "观念约会",
            "活着的装置",
            "艺术学院",
            "新维利亚",
        ):
            if phrase in text and phrase not in repeated_flags:
                repeated_flags.append(phrase)
    return repeated_flags


